mapper.update:
update trade_order
set order_status   = #{status},
    transaction_id = #{transactionId}
where out_trade_no = #{outTradeNo}
  and order_status = 1

mapper.select:
select customer_id
from trade_order
where out_trade_no = #{outTradeNo}

SELECT o.order_id as id, o.out_trade_no AS outTradeNo, o.goods_id AS goodsId, o.snapshot_id AS snapshotId, o.goods_title AS goodsTitle, o.goods_price AS goodsPrice, o.quantity, o.total_amount AS totalAmount, o.goods_image AS goodsImage, o.goods_description AS goodsDescription, o.`order_status` AS orderStatus, IF(o.`order_status` = 1 AND TIMESTAMPDIFF(MINUTE,o.create_time,NOW()) > 20, true, false) AS disabled, DATE_FORMAT(o.create_date,"%Y-%m-%d") AS createDate, DATE_FORMAT(o.create_time,"%Y-%m-%d %H:%i:%s") AS createTime, COUNT(a.order_id) AS appointCount FROM trade_order o LEFT JOIN med_exam_appointment a ON o.order_id = a.order_id WHERE o.customer_id = #{customerId}
AND o.`order_status` = #{orderStatus}
AND ( o.out_trade_no = #{keyword} OR o.goods_title LIKE CONCAT( "%", #{keyword}, "%" ) )
GROUP BY o.order_id ORDER BY o.order_id DESC LIMIT #{startIndex}, #{pageSize}

SELECT COUNT(*)
FROM trade_order
WHERE customer_id = #{customerId}

    AND `order_status` = #{orderStatus}


    AND ( out_trade_no = #{keyword} OR goods_title LIKE CONCAT( "%", #{keyword}, "%" ) )

select out_refund_no as outRefundNo
from trade_order
where order_id = #{orderId}

select transaction_id as transactionId, total_amount as totalAmount
from trade_order
where order_id = #{orderId}
  and order_status = 3
  and customer_id = #{customerId}
